package com.ultron.voice;
import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 TextView status;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(35,70,35,20);l.setBackgroundColor(Color.rgb(5,12,30));TextView title=new TextView(this);title.setText("ULTRON AI\nVOICE ASSISTANT");title.setTextSize(29);title.setTextColor(Color.CYAN);l.addView(title);status=new TextView(this);status.setText("Start listening, then say: Ultron YouTube kholo");status.setTextColor(Color.WHITE);status.setPadding(0,40,0,40);l.addView(status);Button start=new Button(this);start.setText("START HANDS-FREE LISTENING");l.addView(start);Button stop=new Button(this);stop.setText("STOP LISTENING");l.addView(stop);setContentView(l);start.setOnClickListener(v->{if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO,Manifest.permission.CAMERA},10);}else launch();});stop.setOnClickListener(v->{stopService(new Intent(this,ListenService.class));status.setText("Stopped");});}
 void launch(){startForegroundService(new Intent(this,ListenService.class));status.setText("Listening started. Keep the notification visible.");}
 public void onRequestPermissionsResult(int requestCode,String[] p,int[] r){super.onRequestPermissionsResult(requestCode,p,r);if(requestCode==10&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)launch();}
                                                                                                                                                                                                            }
   
